mkdir -p /tmp/sv-73f3f74c36464b20980f25607e024e70/typed-meta && cd /tmp/sv-73f3f74c36464b20980f25607e024e70/typed-meta && dotnet new console --framework net11.0 -o . --force -n TypedMeta > /dev/null 2>&1 && cat > Program.cs << 'EOF'
using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Round-trip using the typed info
var json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Person p = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Deserialized: {p}");

// 2) Probe without throwing: TryGetTypeInfo returns false if unavailable
//    Use an options instance with NO resolver so nothing is resolvable.
var empty = new JsonSerializerOptions { TypeInfoResolver = null };

if (empty.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    Console.WriteLine($"Found metadata: {info!.Type.Name}");
}
else
{
    Console.WriteLine("Metadata not available — no exception thrown.");
}

// Also show TryGetTypeInfo succeeding on the configured options
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info2))
{
    Console.WriteLine($"TryGetTypeInfo succeeded: {info2!.Type.Name}");
}

record Person(string Name, int Age);
EOF
dotnet run

